 return <><AsideHeader className=\"app-shell\" compact={compact} onChangeCompact={setCompact} logo={{text:'teamly',icon:Persons,iconSize:27,textSize:27,iconClassName:'brand-logo',onClick:reset}} subheaderItems={[{item:<div className=\"workspace-switch\"><span className=\"company-icon\">a.</span>{"'!compact&&<><div><strong>Acme Studio</strong><small>Рабочее пространство</small></div><Icon data={ChevronDown} size={14}/></>}</div>,compactItem:<span className="company-icon">a.</span> }]} menuItems={menu} renderFooter={()=> <div className={`sidebar-footer ${compact?'"'is-compact':''}"'`}><Button view="flat" size="l" onClick={()=>setModal('"'Настройки')}><Icon data={Gear} size={18}/>{"'!compact&&'"'Настройки'}</Button><Button view=\"flat\" size=\"l\" onClick={()=>setModal('Помощь')}><Icon data={CircleQuestion} size={18}/>{"'!compact&&'"'Помощь и поддержка'}</Button>{"'!compact&&<div className="sidebar-profile"><Avatar employee={{name:'"'Алексей Ким',color:2}}/><div><strong>Алексей Ким</strong><small>Администратор</small></div><Button view=\"flat\" size=\"s\" aria-label=\"Мой профиль\" onClick={()=>setModal('Мой профиль')}><Icon data={ChevronDown} size={14}/></Button></div>}</div>} renderContent={()=>content}/>
 <Modal open={Boolean(modal)} onClose={()=>setModal('')} aria-label={modal}><div className=\"modal-content\"><div className=\"modal-heading\"><Text variant=\"header-1\">{modal}</Text><Button view=\"flat\" aria-label=\"Закрыть\" onClick={()=>setModal('')}><Icon data={Xmark}/></Button></div>
 {modal==='Добавить сотрудника'?<form onSubmit={e=>{e.preventDefault();if("'!form.name.trim()||!form.role.trim()||!/''^'"\\S+@\\S+\\.\\S+"'$/.test(form.email)){setFormError('"'Укажите имя, должность и корректный email.');return}if(employees.some(e=>e.email.toLowerCase()===form.email.trim().toLowerCase())){setFormError('Сотрудник с таким email уже существует.');return}setEmployees(data=>[{...form,name:form.name.trim(),email:form.email.trim(),role:form.role.trim(),id:crypto.randomUUID(),status:'Активен',date:new Date().toISOString().slice(0,10),color:data.length%6},...data]);reset();setSort([]);setModal('');setNotice('Сотрудник добавлен в команду')}}><p className=\"muted\">Добавьте нового человека в ваше рабочее пространство.</p>{[{key:'name',label:'Имя и фамилия',placeholder:'Например, Анна Смирнова'},{key:'email',label:'Рабочая почта',placeholder:'name@acme.team'},{key:'role',label:'Должность',placeholder:'Например, Product Designer'}].map(field=><label className=\"form-field\" key={field.key}>{field.label}<TextInput size=\"l\" value={form[field.key as keyof typeof form]} placeholder={field.placeholder} onUpdate={v=>setForm({...form,[field.key]:v})} controlProps={{required:true,'aria-label':field.label}} type={field.key==='email'?'email':'text'}/></label>)}<label className=\"form-field\">Отдел<Select size=\"l\" value={[form.department]} options={departments.map(x=>({value:x,content:x}))} onUpdate={v=>setForm({...form,department:v[0]})}/></label>{formError&&<p className=\"form-error\" role=\"alert\">{formError}</p>}<div className=\"modal-actions\"><Button size=\"l\" onClick={()=>setModal('')}>Отмена</Button><Button size=\"l\" view=\"action\" type=\"submit\">Добавить сотрудника</Button></div></form>:
 modal==='Отделы'?<div className=\"department-list\">{departments.map(d=><Button key={d} view=\"outlined\" size=\"xl\" onClick={()=>{setDepartment(d);setStatus('');setPage(1);setModal('')}}>{d}<span className=\"department-total\">{employees.filter(e=>e.department===d).length}</span></Button>)}</div>:
 modal==='Обзор команды'?<><p className=\"muted\">В Acme Studio {employees.length} сотрудников в {departments.length} отделах.</p><div className=\"overview-list\">{statuses.map(s=><div key={s}><Status value={s}/><strong>{count(s)}</strong></div>)}</div></>:
 modal==='Отчёты'?<><p className=\"muted\">Скачайте текущий список сотрудников в CSV. Учитываются фильтры и выделенные строки.</p><Button size=\"l\" view=\"action\" onClick={exportData}><Icon data={ArrowDownToLine}/>Скачать отчёт</Button></>:
 modal==='Настройки'||modal==='Настройки таблицы'?<><label className=\"form-field\">Оформление<Select value={[theme]} size=\"l\" options={[{value:'light',content:'Светлая тема'},{value:'dark',content:'Тёмная тема'}]} onUpdate={v=>setTheme(v[0] as 'light'|'dark')}/></label><label className=\"form-field\">Количество строк на странице<Select value={[String(pageSize)]} size=\"l\" options={[8,16,24,48].map(n=>({value:String(n),content:String(n)}))} onUpdate={v=>{setPageSize(Number(v[0]));setPage(1)}}/></label><Button size=\"l\" view=\"action\" onClick={()=>setModal('')}>Готово</Button></>:
 modal==='Уведомления'?<div className=\"message-empty\"><Icon data={CircleCheck} size={36}/><Text variant=\"subheader-2\">Вы ничего не пропустили</Text><p className=\"muted\">Новых уведомлений пока нет.</p></div>:
 modal==='Мой профиль'?<div className=\"profile-details\"><Avatar employee={{name:'Алексей Ким',color:2}} large/><Text variant=\"header-1\">Алексей Ким</Text><span className=\"muted\">Администратор · Acme Studio</span><span>alexey.kim@acme.team</span></div>:
 <div className=\"help-text\"><p>Нажмите на заголовок колонки, чтобы отсортировать сотрудников. Повторное нажатие изменит направление сортировки.</p><p>Чекбокс в заголовке выбирает все строки текущей страницы. Выделение сохраняется при переходе между страницами.</p><p>Используйте поиск и фильтры, чтобы найти нужных людей, и «Экспорт», чтобы скачать список в CSV.</p></div>}
 </div></Modal>
